export type MotionType2D = 'dynamic' | 'static' | 'kinematic';
export type BodyType2D = MotionType2D;
export interface Rigid2DOptions {
    motion?: MotionType2D;
    type?: MotionType2D;
    density?: number;
    mass?: number;
    friction?: number;
    restitution?: number;
    isSensor?: boolean;
    lockRotation?: boolean;
    fixedRotation?: boolean;
    linearDamping?: number;
    angularDamping?: number;
    ccd?: boolean;
    bullet?: boolean;
    gravityScale?: number;
}
export type Collider2DOptions = Rigid2DOptions;
export interface BasePhysics2DOptions {
    gravity?: [
        number,
        number
    ] | Vec2;
    timeStep?: number;
    velocityIterations?: number;
    positionIterations?: number;
    maxSubSteps?: number;
    autoStep?: boolean;
}
export interface Collision2DEvent {
    entityA: any;
    entityB: any;
    componentA: any;
    componentB: any;
    started: boolean;
}
export interface MouseDragOptions {
    frequencyHz?: number;
    dampingRatio?: number;
    maxForce?: number;
}
export interface SoftBody2DOptions {
    shape?: 'radial' | 'grid';
    mass?: number;
    density?: number;
    frequencyHz?: number;
    dampingRatio?: number;
    stiffness?: number;
    damping?: number;
    friction?: number;
    restitution?: number;
    frictionAir?: number;
    columns?: number;
    rows?: number;
    pinned?: 'top-edge' | 'corners' | number[] | ((col: number, row: number, x: number, y: number) => boolean);
}
export type Physics2DBackendType = 'planck' | 'rapier' | (string & {});
export type Physics2DOptions<B extends Physics2DBackendType = 'planck'> = BasePhysics2DOptions & {
    backend?: B;
};
export type Joint2DType = 'revolute' | 'distance' | 'spring' | 'fixed' | 'prismatic' | 'rope';
export interface BaseJoint2DOptions {
    entityA: any;
    entityB: any;
    localAnchorA?: {
        x: number;
        y: number;
    };
    localAnchorB?: {
        x: number;
        y: number;
    };
    worldAnchor?: {
        x: number;
        y: number;
    };
    collideConnected?: boolean;
}
export interface RevoluteJoint2DOptions extends BaseJoint2DOptions {
    type?: 'revolute';
    limits?: [
        number,
        number
    ];
    enableLimit?: boolean;
    motorSpeed?: number;
    maxMotorTorque?: number;
    enableMotor?: boolean;
}
export interface DistanceJoint2DOptions extends BaseJoint2DOptions {
    type?: 'distance' | 'spring';
    length?: number;
    frequencyHz?: number;
    dampingRatio?: number;
    stiffness?: number;
    damping?: number;
}
export type SpringJoint2DOptions = DistanceJoint2DOptions;
export interface FixedJoint2DOptions extends BaseJoint2DOptions {
    type?: 'fixed';
}
export interface PrismaticJoint2DOptions extends BaseJoint2DOptions {
    type?: 'prismatic';
    axis?: {
        x: number;
        y: number;
    };
    limits?: [
        number,
        number
    ];
    enableLimit?: boolean;
    motorSpeed?: number;
    maxMotorForce?: number;
    enableMotor?: boolean;
}
export interface RopeJoint2DOptions extends BaseJoint2DOptions {
    type?: 'rope';
    maxLength?: number;
}
export type Joint2DOptions = (RevoluteJoint2DOptions & {
    type: 'revolute';
}) | (DistanceJoint2DOptions & {
    type: 'distance';
}) | (SpringJoint2DOptions & {
    type: 'spring';
}) | (FixedJoint2DOptions & {
    type: 'fixed';
}) | (PrismaticJoint2DOptions & {
    type: 'prismatic';
}) | (RopeJoint2DOptions & {
    type: 'rope';
});

